/** Each union expanded once; a selection field references one by name. */
export const foirSelectionUnions: Record<string, FoirManifestSelectionUnion> = {};

/**
 * The Subscription root fields this credential reaches, with the resolved
 * payload selection for each.
 *
 * Without these a subscribing client fetched `GET /v1/manifest` even when it
 * was built with a generated module, because the module carried model trees
 * only. That made passing `generated` strictly worse for a subscribe-only
 * client: the bundle cost, and the round trip anyway.
 */
export const foirSubscriptions: FoirManifestSubscription[] = [
  {
    "argScope": {
      "arg": "modelKey",
      "prefix": "records:read:",
      "values": [
        "audience",
        "follow-approval",
        "follow-request",
        "profile"
      ]
    },
    "argTypes": {
      "after": "EventSeq",
      "modelKey": "String!"
    },
    "args": [
      "after",
      "modelKey"
    ],
    "field": "recordChanged",
    "selection": {
      "cost": 7,
      "fields": [
        {
          "key": "action"
        },
        {
          "key": "event"
        },
        {
          "key": "eventId"
        },
        {
          "key": "modelKey"
        },
        {
          "key": "recordId"
        },
        {
          "key": "seq"
        },
        {
          "key": "userId"
        }
      ]
    },
    "type": "RecordChangedEvent"
  }
];
